/**
 * Membership tier badges (user-provided artwork, 2026-09-21): hexagonal "V"
 * medallions, one per paid tier — standard (violet), advanced (copper),
 * elite (gold). 120×120 PNGs with the hexagon shape baked into the alpha
 * channel, inlined as data URIs so Vite and Next.js resolve them identically
 * — same approach as ../about/app-icon.ts.
 */

export const MEMBER_BADGE_STANDARD_SRC =
  "data:image/png;base64,";
export const MEMBER_BADGE_ADVANCED_SRC =
  "data:image/png;base64,";
export const MEMBER_BADGE_ELITE_SRC =
  "data:image/png;base64,";

/**
 * Maps a raw API memberLevel to its badge artwork, mirroring the tier names
 * in useLocalizedPlan. Returns null for free/trial/empty/unknown levels —
 * an unrecognized tier never earns a badge rather than guessing one.
 */
export function memberBadgeSrc(rawLevel: string | undefined): string | null {
  const key = (rawLevel ?? "").toLowerCase();
  if (key === "elite") return MEMBER_BADGE_ELITE_SRC;
  if (key === "advanced" || key === "premium") return MEMBER_BADGE_ADVANCED_SRC;
  if (key === "standard" || key === "basic") return MEMBER_BADGE_STANDARD_SRC;
  return null;
}
